#!/usr/bin/env bash
# REVISION 3B s70 — sensor (m4rk). Directorio NUEVO ~/cf-3b-revision-20261101; solo LEE ~/cf-3b-20261101T0721Z.
# 1) copia herramientas originales + v2 (embebidas) y verifica hashes  2) respaldos v2 + integridad v2
# 3) recálculo v2 de características en segundo plano (nohup; ~50 min)
set -u
B=$HOME/cf-3b-20261101T0721Z; R=$HOME/cf-3b-revision-20261101; C=$B/copias; PY=$HOME/cyberflow/.venv/bin/python
[ -e "$R" ] && { echo "PARAR: existe $R"; exit 2; }
mkdir -p $R/herramientas; cp -p $B/herramientas/*.py $B/herramientas/config-campana-3b.json $R/herramientas/
cd $R/herramientas
base64 -d > generar_respaldos_v2.py <<'B64'

B64
base64 -d > verificar_integridad_v2.py <<'B64'

B64
base64 -d > recalcular_caracteristicas_v2.py <<'B64'

B64
echo "## $(date -u +%FT%T.%3NZ) hashes de herramientas"; sha256sum *.py config-campana-3b.json | tee $R/sha256-herramientas.txt
echo "## hashes de entradas"; sha256sum $C/marcas.jsonl $C/motor_decision.log $C/eve-segmento.json $C/ciclos.jsonl $B/replay/motor_decision.log $B/analisis/caracteristicas.jsonl $C/descartes-tcpdump.json $B/analisis/suricata-stats.json | tee $R/sha256-entradas.txt
echo "## respaldos v2"; python3 generar_respaldos_v2.py --marcas $C/marcas.jsonl --motor $C/motor_decision.log --eve $C/eve-segmento.json \
  --caracteristicas $B/analisis/caracteristicas.jsonl --pcap-dir $B/archivo-pcap --relojes $C/relojes-3b.log \
  --servicios-inicio $B/estado-inicial/servicios.txt --servicios-fin $C/servicios-fin.txt --suricata-stats $B/analisis/suricata-stats.json \
  --descartes-tcpdump $C/descartes-tcpdump.json --inventario $B/replay/motor_decision.log \
  --inventario-rango "2026-11-01T07:24:40Z,2026-11-01T10:05:30Z" --historia 230 \
  --campana campana-A-repetida-3b-20261101T0721Z --salida-dir $R/respaldos-v2 > $R/respaldos.stdout 2> $R/respaldos.stderr; echo "  rc=$?"; tail -2 $R/respaldos.stdout; tail -3 $R/respaldos.stderr
echo "## integridad v2"; python3 verificar_integridad_v2.py --descriptor $R/respaldos-v2/descriptor-integridad.json --salida $R/integridad-v2.json > $R/integridad.stdout 2> $R/integridad.stderr; echo "  rc=$?"; cat $R/integridad.stdout; tail -3 $R/integridad.stderr
echo "## recálculo v2 en segundo plano"; AR=$(cat $HOME/cf-paso2-20261101T0254Z/reinicio.t); echo "  arranque=$AR"
setsid nohup bash -c "$PY recalcular_caracteristicas_v2.py --marcas $C/marcas.jsonl --motor $C/motor_decision.log --pcap-dir $B/archivo-pcap --eve $C/eve-segmento.json --arranque-motor $AR --salida $R/caracteristicas-v2.jsonl > $R/recalculo.stdout 2> $R/recalculo.stderr; echo \$? > $R/recalculo.rc" > /dev/null 2>&1 < /dev/null &
echo "  pid=$!"; echo "## fin $(date -u +%FT%T.%3NZ)"
